def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find vertical runs of a non-background color that can serve as borders.
    runs = []
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
                continue
            color = grid[r][c]
            start = r
            while r < h and grid[r][c] == color:
                r += 1
            if r - start >= 2:
                runs.append((start, r, c, color))

    # Each isolated marker rays toward its nearest border. Its row also fills
    # the corresponding row of the matching, opposite border segment.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            if any(a <= r < b and bc == c and col == color
                   for a, b, bc, col in runs):
                continue

            candidates = [run for run in runs if run[0] <= r < run[1]]
            if not candidates:
                continue
            source = min(candidates, key=lambda run: abs(run[2] - c))
            a, b, sc, _ = source

            partners = [run for run in runs
                        if run != source and run[1] - run[0] == b - a]
            if partners:
                target = min(partners, key=lambda run: abs(run[2] - sc))
                ta, _, tc, _ = target
                tr = ta + (r - a)
                for x in range(w):
                    if x != tc:
                        out[tr][x] = color

            step = 1 if c > sc else -1
            x = sc + step
            while x != c:
                out[r][x] = color
                x += step
            out[r][c] = 4

    return out
